export default [{"id":3311,"question":"حديث المحبة يذكر في الحب: تقديم سنة النبي ﷺ أيضًا؟","title":"ما حقيقة محبة الله تعالى والمحبة لغير الله؟","answer":"الجواب: نعم من تمام المحبة تقديم محبة النبي ﷺ، وتقديم طاعة الله في أداء الفرائض وترك المحارم، ومِنْ ضَعْف المحبة وقوع المعاصي.\n..... المحبة لغير الله: المحبة التي يحصل بها عبادة غير الله، يستغيث بهم، وينذر لهم، ويسب الدِّين من أجلهم، المقصود: يعني يحصل به عبادة لغير الله كما فعل المشركون بآلهتهم، يحبونهم كحب الله بدعوتهم، والاستغاثة بهم، والنذر لهم، ونحو ذلك، المقصود إذا كان معها عبادة لغير الله. أما كونه أحب أهل بيته أو أحب جماعته وآثرهم حتى عصى الله من أجلهم يكون نقص في الإيمان، وضعف في الإيمان، وقد يعصي الله لأجل زوجته، وقد يعصي الله لأجل ولده، وقد يعصي الله لأجل أبيه؛ فهذا نقص في الإيمان، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23477/ما-حقيقة-محبة-الله-تعالى-والمحبة-لغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تمام محبة الله تقديم سنة رسول الله.mp3","categories":["الربوبية والألوهية"]},{"id":4291,"question":"الذين لم يفعلوا خيرًا من أهل التوحيد؟","title":"حكم الذين لم يفعلوا خيرًا من أهل التوحيد","answer":"الجواب: إلا التوحيد.\nس: هؤلاء كانوا ما يصلون على حسب النص؟\nج: ماتوا على شيء لا يكفّرهم، معاصٍ لا تكفّرهم.\nس: ما كانوا يصلون؟\nج: اللي ما يصلي ما عمل خيرًا قط؛ لأن عدم الصلاة يبطل أعماله، ما يكون موحدًا، يكون مع الكفرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24563/حكم-الذين-لم-يفعلوا-خيرا-من-اهل-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الذين لم يفعلوا خيرًا من أهل التوحيد.mp3","categories":["الربوبية والألوهية"]},{"id":4319,"question":"الحكمة في تثنية المؤلف في \"باب حماية جناب التوحيد\" ومرة في \"حماية حمى التوحيد\"؟","title":"ما معنى جناب التوحيد وحماه والفرق بينهما؟","answer":"الجواب: الجناب جزء من الشيء، والحمى ما وراءه، حمى الشيء ما وراءه، والرسول ﷺ حمى الحمى، وحمى جانبه، جانب التوحيد، يعني: ما أوجب الله على العباد من الطاعات، حماها من الشرك، ثم حمى الحمى بقوله لما قالوا له أنت سيدنا قال: السيد الله تبارك وتعالى وقال: قولوا بقولكم أو بعض قولكم ولا يستهوينكم الشيطان مع أنه سيد الخلق عليه الصلاة والسلام، لكن حمى الحمى؛ لئلا يغلوا فيه؛ لئلا يتخذوا الجائز وسيلة إلى المحرم.","link":"https://binbaz.org.sa/fatwas/24593/ما-معنى-جناب-التوحيد-وحماه-والفرق-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكمة في أن الإمام محمد عبد الوهاب عقد باب حماية جناب التوحيد، وعقد باب حماية.mp3","categories":["الربوبية والألوهية"]},{"id":5169,"question":"هذا يقول: وظيفتي وطبيعة عملي تستدعي مُخالطة جاليات غير مسلمة ومعاشرتهم، وقد نُفطر معًا في مقر العمل، وقد نبدأهم بالسلام أو التحية، فكيف نُحقق جانب الولاء والبراء مع هؤلاء؟","title":"كيف يكون الولاء والبراء مع الزملاء غير المسلمين؟","answer":"الجواب: عليك أن تنصحهم وتدعوهم إلى الله، وتُعاملهم بما تدعو الحاجةُ إليه: سؤالهم عن معاملة، إعطاؤهم معاملة يعملونها، ردّ السلام عليهم إذا سلَّموا هم، ولا تبدأهم أنت، وهكذا، أما اتِّخاذهم أصحابًا وأحبابًا ومُعاشرتهم كأنَّهم مسلمون فلا، ما يجوز هذا، لكن تُعاملهم بما تدعو الحاجة إليه في أنظمة الوظيفة: من معاملة تُعطى إياه، أو تُؤخذ منه، أو يُسأل عنها: أين ذهبت؟ أين جئت؟ ولا بأس أن يُقال: كيف أولادك؟ كيف حالك؟ لأنَّ هذا ليس من البدء بالسلام، وإذا سلّم تقول: وعليكم السلام.","link":"https://binbaz.org.sa/fatwas/30094/كيف-يكون-الولاء-والبراء-مع-الزملاء-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 118.mp3","categories":["الربوبية والألوهية"]},{"id":5513,"question":"بعض الناس يقول: إنَّ الحاكمية هي أخصّ خصائص الألوهية؟","title":"ما أخصّ خصائص الألوهية؟","answer":"الجواب: أخصّها: ترك الشرك، الحاكمية من فروع الأحكام، يجب على الحاكم أن يحكم بالشرع، أما إذا حكم بغير الشرع فيه تفصيل: إذا حكم به عن عمدٍ واستحلالٍ كفر، وإن حكم لهوى ورشوةٍ صار معصيةً ومنكرًا وكفرًا أصغر، فهذه من مفردات الشرائع التابعة لتوحيد العبادة. س: تدخل في توحيد الربوبية أو توحيد الألوهية؟ ج: تختلف: تارةً تدخل في الكفر، وتارةً تدخل في المعاصي، مثل: مسألة الزنا، ومسألة الخمر، إن استحلَّها صار كفرًا، وإن لم يستحلها صار معصيةً.[1]","link":"https://binbaz.org.sa/fatwas/31445/ما-اخص-خصاىص-الالوهية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 028.mp3","categories":["الربوبية والألوهية"]},{"id":5522,"question":"إذا لم يأتِ بشروط (لا إله إلا الله) السبعة؟","title":"ما حكم مَنْ لم يأتِ بشروط (لا إله إلا الله) السبعة؟","answer":"الجواب: إذا كان يؤمن بمعناها ولو ما عرف الشروط، إذا كان يعرف معناها، وأنَّه لا معبودَ إلا الله، ولو ما عرف الشروط، فالعامِّي قد لا يعرف الشروط، المهم أن يُؤمن بالله وحده، وأنه المعبود بحقٍّ، وما سواه باطل، يكفي.[1]","link":"https://binbaz.org.sa/fatwas/31455/ما-حكم-من-لم-يات-بشروط-لا-اله-الا-الله-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 037.mp3","categories":["الربوبية والألوهية"]},{"id":6444,"question":"نسمع كثيرًا في المذياع عن توحيد الربوبية، والألوهية، فما الفرق بينهما؟","title":"بيان أنواع التوحيد والفرق بينها","answer":"الجواب: توحيد الربوبية: هو الإيمان بالله بصفات الفعل، كالخلاق، والرزاق، ومدبر الأمور، ومصرفها، ونحو ذلك، وأن مشيئته نافذة، وقدرته كاملة، وهذا هو الذي أقر به المشركون، المشركون أقروا بأن الله خالقهم، ورازقهم، ومدبر أمورهم، وأنه خالق السماوات، وخالق الأرض، وهو توحيد الله بأفعاله، هذا توحيد الربوبية بأن تؤمن بأن الله هو الخلاق، الرزاق، مدبر الأمور، مصرف الأشياء، الذي خلق كل شيء، ودبر الأمور، وصرفها، وخلق الأنهار، والبحار، والجبال، والأشجار، والسماء، والأرض، وغير ذلك، هذا توحيد الربوبية. أما توحيد الألوهية: فهو توحيد الله بأفعالك أنت، تخصه بالعبادة دون كل ما سواه، من صلاة، وصوم، ودعاء، ونذر، وزكاة، وحج، وغير ذلك،. توحيد الألوهية: هو معنى لا إله إلا الله، أي لا معبود حق إلا الله، وهو أن تخص ربك بأفعالك، بعباداتك، بقرباتك، لا تدعو مع الله إلهًا آخر، لا تعبد معه سواه من شجر، أو حجر، أو صنم، أو نبي، أو ولي، فلا تدعو غير الله، لا تقول: يا سيدي البدوي اشفني، أو يا رسول الله، اشفني، أو عافني، أو انصرني، أو يا فلان، أو يا فلان من الأولياء، أو من غير الأولياء من الأموات، أو من الأشجار، والأحجار، والأصنام، هذا الشرك الأكبر. فتوحيد العبادة معناه: أن تخص العبادة لله وحده، ويقال له: توحيد الإلهية، والإلهية هي العبادة، معناه: أن يخص الله بالعبادة دون كل ما سواه، وهذا هو معنى قوله سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5].  وقوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] معناه أن يخصوا الله بالعبادة بصلاتهم، وصومهم، ودعائهم، واستغاثتهم، وجهادهم كله لله وحده، هذا يسمى توحيد العبادة، ويسمى توحيد الإلهية، وهذا أنكره المشركون، وأبوه، ولما قال: قولوا لا إله إلا الله أبوا، واستنكروها، وقالوا: أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ [ص:5] فاستنكروا ذلك، وأصروا على كفرهم، وضلالهم، وهم يقولون: الله الخالق، الرازق، المدبر، يقولون: هذا، ولكن مع ذلك لم يخضعوا لتوحيدهم العبادة .... فلهذا صاروا كافرين، وقاتلهم النبي ﷺ واستحل دماءهم، وأموالهم لكفرهم، وعدم إذعانهم بتوحيد الإلهية. وهناك توحيد ثالث، وهو توحيد الأسماء والصفات، وهو: الإيمان بأسماء الله وصفاته، كلها التي جاءت في القرآن، والتي صحت بها السنة عن النبي ﷺ لا بدّ من الإيمان بها كلها، وإثباتها بأنه العليم الحكيم، الرؤوف الرحيم، وأنه يرضى ويغضب، ويتكلم إذا شاء  جميع صفاته في القرآن، والسنة لا بدّ من الإيمان بها، وإثباتها لله  وهذا يسمى توحيد الأسماء والصفات. والإيمان بأن الله واحد في ذاته، واحد في أسمائه، وصفاته، لا شريك له، ليس له شريك يخلق، أو يرزق، أو يرحم العباد حتى يدخلهم الجنة، وينجيهم من النار، وليس له شريك في القدرة، وأنه قادر على كل شيء، بل هو منفرد بهذا  فليس له شريك في إلهيته، ولا في أسمائه، وصفاته، ولا في ربوبيته . فهو الواحد في الربوبية، هو الواحد في الإلهية، هو الواحد في الأسماء والصفات، لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ[الشورى:11]، هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65] وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ [النحل:74]. فأسماؤه كلها حسنى، وصفاته كلها علا، وكلها حق له ثابت، وهو  موصوف بها حقًا لا مجازًا، فيجب إثباتها لله، وإمرارها كما جاءت، والإيمان بها، وأنها حق لائقة بالله  وأنه  ليس كمثله شيء في ذلك، وهو السميع البصير .","link":"https://binbaz.org.sa/fatwas/2190/بيان-انواع-التوحيد-والفرق-بينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_815.mp3","categories":["الربوبية والألوهية"]},{"id":6465,"question":"نسمع كثيرًا في المذياع عن توحيد الربوبية، والألوهية، فما الفرق بينهما؟","title":"بيان أنواع التوحيد والفرق بينها","answer":"الجواب: توحيد الربوبية: هو الإيمان بالله بصفات الفعل، كالخلاق، والرزاق، ومدبر الأمور، ومصرفها، ونحو ذلك، وأن مشيئته نافذة، وقدرته كاملة، وهذا هو الذي أقر به المشركون، المشركون أقروا بأن الله خالقهم، ورازقهم، ومدبر أمورهم، وأنه خالق السماوات، وخالق الأرض، وهو توحيد الله بأفعاله، هذا توحيد الربوبية بأن تؤمن بأن الله هو الخلاق، الرزاق، مدبر الأمور، مصرف الأشياء، الذي خلق كل شيء، ودبر الأمور، وصرفها، وخلق الأنهار، والبحار، والجبال، والأشجار، والسماء، والأرض، وغير ذلك، هذا توحيد الربوبية. أما توحيد الألوهية: فهو توحيد الله بأفعالك أنت، تخصه بالعبادة دون كل ما سواه، من صلاة، وصوم، ودعاء، ونذر، وزكاة، وحج، وغير ذلك،. توحيد الألوهية: هو معنى لا إله إلا الله، أي لا معبود حق إلا الله، وهو أن تخص ربك بأفعالك، بعباداتك، بقرباتك، لا تدعو مع الله إلهًا آخر، لا تعبد معه سواه من شجر، أو حجر، أو صنم، أو نبي، أو ولي، فلا تدعو غير الله، لا تقول: يا سيدي البدوي اشفني، أو يا رسول الله، اشفني، أو عافني، أو انصرني، أو يا فلان، أو يا فلان من الأولياء، أو من غير الأولياء من الأموات، أو من الأشجار، والأحجار، والأصنام، هذا الشرك الأكبر. فتوحيد العبادة معناه: أن تخص العبادة لله وحده، ويقال له: توحيد الإلهية، والإلهية هي العبادة، معناه: أن يخص الله بالعبادة دون كل ما سواه، وهذا هو معنى قوله سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5].  وقوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] معناه أن يخصوا الله بالعبادة بصلاتهم، وصومهم، ودعائهم، واستغاثتهم، وجهادهم كله لله وحده، هذا يسمى توحيد العبادة، ويسمى توحيد الإلهية، وهذا أنكره المشركون، وأبوه، ولما قال: قولوا لا إله إلا الله أبوا، واستنكروها، وقالوا: أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ [ص:5] فاستنكروا ذلك، وأصروا على كفرهم، وضلالهم، وهم يقولون: الله الخالق، الرازق، المدبر، يقولون: هذا، ولكن مع ذلك لم يخضعوا لتوحيدهم العبادة .... فلهذا صاروا كافرين، وقاتلهم النبي ﷺ واستحل دماءهم، وأموالهم لكفرهم، وعدم إذعانهم بتوحيد الإلهية. وهناك توحيد ثالث، وهو توحيد الأسماء والصفات، وهو: الإيمان بأسماء الله وصفاته، كلها التي جاءت في القرآن، والتي صحت بها السنة عن النبي ﷺ لا بدّ من الإيمان بها كلها، وإثباتها بأنه العليم الحكيم، الرؤوف الرحيم، وأنه يرضى ويغضب، ويتكلم إذا شاء  جميع صفاته في القرآن، والسنة لا بدّ من الإيمان بها، وإثباتها لله  وهذا يسمى توحيد الأسماء والصفات. والإيمان بأن الله واحد في ذاته، واحد في أسمائه، وصفاته، لا شريك له، ليس له شريك يخلق، أو يرزق، أو يرحم العباد حتى يدخلهم الجنة، وينجيهم من النار، وليس له شريك في القدرة، وأنه قادر على كل شيء، بل هو منفرد بهذا  فليس له شريك في إلهيته، ولا في أسمائه، وصفاته، ولا في ربوبيته . فهو الواحد في الربوبية، هو الواحد في الإلهية، هو الواحد في الأسماء والصفات، لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ[الشورى:11]، هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65] وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ [النحل:74]. فأسماؤه كلها حسنى، وصفاته كلها علا، وكلها حق له ثابت، وهو  موصوف بها حقًا لا مجازًا، فيجب إثباتها لله، وإمرارها كما جاءت، والإيمان بها، وأنها حق لائقة بالله  وأنه  ليس كمثله شيء في ذلك، وهو السميع البصير .","link":"https://binbaz.org.sa/fatwas/2190/بيان-انواع-التوحيد-والفرق-بينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_815.mp3","categories":["الربوبية والألوهية"]},{"id":6600,"question":"ذكرتم في إحدى فتاويكم حول تفسير الآية الكريمة لَا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ[المجادلة:22] الآية أن من أحب الكفار، ووادهم؛ فهو كافر كفرًا يخرج عن الملة، فآمل توضيح ذلك، وهل المقصود بالكفار هم الذين في حرب مع المسلمين؟","title":"حكم موالاة الكفار ومحبتهم","answer":"الجواب:  نعم من أحب الكفار -اليهود والنصارى والمشركين- ولو كانوا في عهد، وليسوا في حرب، من أحبهم لدينهم، والرضا بدينهم، والتعاون معهم على مصالح دينهم، ونحو ذلك؛ فهو مثلهم، أما إن أحب قومًا حبًا خاصًا؛ لأنهم أعطوه كذا، أو لأنهم قرابات، يحبهم لقراباتهم، لا لدينهم، هذه معصية كبيرة. وأما إذا أحبهم لدينهم، ولأخلاقهم، ولما هم عليه، ويفضلهم على المسلمين، ويرى أنه على هدى، وعلى خير، فهذا -والعياذ بالله- ردة ظاهرة، وكفر ظاهر، نسأل الله العافية؛ لأن الموالاة قسمان:  موالاة: معناها المحبة، والنصرة، والتأييد لهم على المسلمين، والرضا بدينهم، وأخلاقهم، هذا كفر أكبر. وتارة: قد يحب بعض الناس لقرابة، أو لكونها زوجته من أهل الكتاب، أو لكونه قريبًا له يحبه، ويتولاه بالهداية، ونحو ذلك، ولكن لا يحب دينه، ولا يرضى بدينه، ولا يوالي على دينه، فهذه محبة ناقصة، محبة خاصة لأجل قرابة، أو صلة أخرى، فهذه محبة تنقص دينه، وتضعف دينه، ويجب عليه أن يبغضهم في الله، ومعاداتهم في الله، لكن لا تكون ردة كبرى، بل هي دون ذلك، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2460/حكم-موالاة-الكفار-ومحبتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_987.mp3","categories":["الربوبية والألوهية"]},{"id":6658,"question":"لماذا قرنت الشهادتان في ركن واحد من أركان الإسلام، بالرغم أن المراد اثنان هما الألوهية لله، والرسالة لمحمد؟","title":"سبب اقتران الشهادتين في ركن واحد","answer":"الجواب: لا بد من هذا وهذا، لا بد من الشهادتين، لكن مقام الشهادة لله الوحدانية أعظم، وأهم، وأكبر، لأن كثيرًا من الناس لا يشق عليهم أن يقولوا: محمد رسول الله، ويقرون بالرسالة، لكنهم لا يطبقون معنى لا إله إلا الله، فلهذا نبه الإخوان على هذه الكلمة بالشهادة فيها، ويأتي مزيد التنبيه على شهادة أن محمدًا رسول الله في الندوات الأخرى.  لكن هذه الكلمة مع الرسل كلهم، ما هو مع محمد وحده، مع نوح، مع آدم، ومع هود، ومع صالح، ومع إبراهيم، ومع لوط، ومع من بعدهم من الأنبياء: موسى، وهارون، وعيسى، وداود، وسليمان، وغيرهم من الرسل، والأنبياء، هذا .. فتحقيق هذا شيء لا بد منها من عهد آدم إلى يومنا هذا، لا بد من تحقيق لا إله إلا الله، ولا بد من معرفة معناها، والقيام بحقها، وإخلاص العبادة لله وحده في كل زمان، من عهد آدم إلى يومنا هذا. وعلى أمة محمد ﷺ مع ذلك أن يؤمنوا بمحمد ﷺ مع بقية المرسلين، كما أن على من كان في عصر آدم، كون أبينا آدم نبيا -عليه الصلاة والسلام- مبعوثا إليهم، مرسلًا إليهم، ويأخذون بشريعته، كما أن على من كان في عهد نوح أن يؤمنوا بنوح مع توحيد الله، وعلى من كان في عهد هود أن يوحد الله، ويصدق هودًا، ويتبع شريعته، وهكذا من كان في عهد صالح يوحد الله، ويؤمن بهذه الكلمة، ويصدق صالحًا في ما جاء به، ويتبع شريعته، وهكذا من كان في عهد إبراهيم، وعهد لوط، وعهد موسى، وهارون، وغيرهم، كل أمة عليها أن تؤمن برسولها مع توحيد الله، ومع الإخلاص لله.  وعلى الأمة الأخيرة أمة محمد -عليه الصلاة والسلام- عليها أن توحد الله، وعليها أن تصدق رسولها محمداً ﷺ وتنقاد لشريعته، لا بد من هذا وهذا، لا بد من الشهادتين، لا تكفي إحداهما عن الأخرى، فلو وحد الله، وعبده وحده، وترك المعاصي، ولكنه لا يؤمن بأن محمدًا رسول الله؛ فهو كافر، حلال الدم، والمال عند جميع أهل العلم، فلو صدق الرسول ﷺ وآمن به، وقال: إنه رسول الله، ولكنه لم يأت بمعنى لا إله إلا الله، لم يعبد الله، بل عبد معه سواه، أو سب الله، أو فعل ما يوجب نقض إسلامه؛ لم تنفعه شهادة أن محمدًا رسول الله، فلا بد من الشهادتين، ولا بد من تحقيقهما والعمل بمقتضاهما، ثم العمل بعد ذلك بالصلاة، والزكاة، وغير ذلك.","link":"https://binbaz.org.sa/fatwas/2554/سبب-اقتران-الشهادتين-في-ركن-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1049.mp3","categories":["الربوبية والألوهية"]},{"id":6668,"question":"ماهية التوكل، ولماذا شبه في الحديث بالطير، جزاكم الله خيرًا؟","title":"ما حقيقة التوكل؟","answer":"الجواب: التوكل حقيقته الاعتماد على الله، والثقة بالله، والإيمان بأنه مسبب الأسباب، وأنه مقدر الأمور، وأن الشيء بيده، ومصرف الأشياء  ما شاء كان، وما لم يشأ لم يكن  مع تعاطي الأسباب، مع الأخذ بالأسباب من الأكل، والشرب، والكي، والطب، وغير ذلك، فالتوكل مرتب أمرين: الأمر الأول: الاعتماد على الله، والإيمان بأنه مسبب الأسباب، وأنه بيده تصريف الأمور، وأن ما شاء الله [كان] وما لم يشأ لم يكن .  والأمر الثاني: الأخذ بالأسباب التي شرعها الله من أسباب الجنة، وأسباب العافية.","link":"https://binbaz.org.sa/fatwas/2568/ما-حقيقة-التوكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1063.mp3","categories":["الربوبية والألوهية"]},{"id":6687,"question":"إذا قال الواعظ مفسرًا لا إله إلا الله قال: لا خالق إلا الله، لا رازق، ولا مدبر إلا الله، وأن الخلق، والأمر لله، فبهذا لا يعبد إلا الله، ولم يتطرق لنفي غير الله، ونفي الشرك، والتحذير منه، هل يكفي هذا؟ وما هو المعنى الكامل مختصرًا؟","title":"خطأ في تفسير كلمة: لا إله إلا الله","answer":"الجواب: هذا غلط، فإن لا خالق إلا الله، ولا رازق إلا الله هذا يقولها أبو جهل، ويقوله الكفار المشركون الأولون، يقولون: لا خالق إلا الله وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ [الزخرف: 87] وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ [الزمر : 38] هم مقرون بهذا، ولكن إذا قيل لهم: قولوا لا إله إلا الله قالوا لا: إِنَّهُمْ كَانُوا إِذَا قِيلَ لَهُمْ لَا إِلَهَ إِلَّا اللَّهُ يَسْتَكْبِرُونَ [الصافات : 35] ويقولون: أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ   [ص: 5].  فلا بد من بيان معنى لا إله إلا الله، وأن معناها: لا معبود حق إلا الله، وأنه لا يدعى إلا الله، لا يستغاث إلا بالله، لا ينذر إلا لله، لا يذبح إلا لله، بين معنى ذلك، مع أنه لا خالق إلا الله، مع هذا وهذا، لا خالق إلا الله، ولا رازق إلا الله، .. لكن مع هذا ... هو الإله الحق، هو الذي يجب يعبد .. بالصلاة، والصوم، والنذر، والذبح، والرغبة، والرهبة، والخوف، والرجاء، وغير ذلك من العبادات، فمن جعل هذا لغير الله من كوكب، أو ملك، أو ميت، أو صنم؛ صار عابداً لذلك الشيء، وصار قد أشرك به مع الله .","link":"https://binbaz.org.sa/fatwas/2556/خطا-في-تفسير-كلمة-لا-اله-الا-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1051.mp3","categories":["الربوبية والألوهية"]},{"id":7367,"question":"هل يكون الحب والبغض لنفس الشخص، أم لعمله؟","title":"الحب والبغض يكون لعمل الشخص لا لذاته","answer":"الجواب: الحب والبغض لعمله؛ إن كان مؤمنًا؛ أحبه لإيمانه، وإن كان كافرًا؛ أبغضه لكفره، لا من أجل نسبه، ولا من أجل كونه أبيض أو أسود، لا. يحب لإيمانه وتقواه، وإن كان أقبح الناس صورة، ويبغض لكفره وضلاله، وإن كان أحسن الناس صورة، وإن كان أكثرهم مالًا.","link":"https://binbaz.org.sa/fatwas/3446/الحب-والبغض-يكون-لعمل-الشخص-لا-لذاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1752.mp3","categories":["الربوبية والألوهية"]},{"id":8693,"question":"الواقع الأسئلة كثيرة حول هذا الموضوع، ويبدو لي أنه لا غرابة في ذلك سماحة الشيخ أسأل: لو تكرمتم النطق بالشهادة لا شك أن له تصديق، ما مصداقية ذلك سماحة الشيخ؟","title":"مظاهر مصداقية النطق بالشهادتين","answer":"الجواب: أولاً: لابد من الأمر بالشهادة، لو أنكر النطق بها ولم ينطق بها وهو يقدر كفر حتى ينطق بالشهادتين لابد، ثم مع النطق لابد من العقيدة والإيمان بأن معنى: لا إله إلا الله، معناها: أنه لا معبود بحق إلا الله، فلو قالها وهو يكذب كالمنافقين، يقولها وهو يعتقد أن مع الله آلهة أخرى لم تنفعه هذه الكلمة، كما قال سبحانه: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ [النساء:145]، قال تعالى: وَمِنََ النَّاسِ مَنْ يَقُولُ آمَنَّا بِاللَّهِ وَبِالْيَوْمِ الآخِرِ وَمَا هُمْ بِمُؤْمِنِينَ ۝ يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا وَمَا يَخْدَعُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ[البقرة:8-9]، فلابد من التصديق بالقلب واليقين بأنه لا معبود حق إلا الله، ولابد من إخلاص العبادة لله والمحبة لما دلت عليه من توحيد الله وكراهة الكفر وبغضه، ولابد أيضاً من قبول شرع الله والانقياد له، فإن استكبر عن ذلك ولم ينقد لشرع الله كفر نسأل الله العافية. نعم.\nالمقدم: وهذا معنى النفي والإثبات سماحة الشيخ؟\nالشيخ: نعم، معناها: لا معبود حق إلا الله، (لا إله) معناه: نفي الإلوهية عن غير الله، يعني: اعتقاد بأن إلوهية غيره باطلة، وإلا الله معناه: إثبات العبودية لله وحده وأنه المستحق لها، كما قال : ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ [الحج:62]، الآية من سورة الحج، ومعناها في سورة لقمان أيضاً. نعم.\nالمقدم: بارك الله فيكم، إذاً مصداقية هذه الشهادة وهذا الركن من أركان الإسلام، هي العمل ببقية أركان الإسلام الظاهرة والباطنة التي تفضلتم ببيانها؟\nالشيخ: نعم، نعم، لكنها متفاوتة، بعضها إذا ترك كفر، وبعضها إذا ترك لا يكفر يكون ناقص الإيمان ضعيف الإيمان، إلا إذا جحد ما أوجب الله أو جحد ما حرم الله، إذا جحده كفر عند الجميع، لو جحد وجوب الصلاة كفر عند الجميع، جحد وجوب صيام رمضان كفر عند الجميع، جحد وجوب الزكاة مع توفر شروطها كفر عند الجميع، جحد وجوب الحج مع الاستطاعة كفر عند الجميع، جحد تحريم الزنا يكفر عند الجميع، جحد تحريم الخمر قال: ما هو بحرام كفر عند الجميع، جحد عقوق الوالدين قال: ليس عقوقهما بحرام يجوز عقوق الوالدين كفر بالإجماع نسأل الله العافية، وهكذا ما أشبه هذا من الأمور الظاهرة، أمور الدين المعروفة بالوجوب أو بالتحريم. نعم.","link":"https://binbaz.org.sa/fatwas/6840/مظاهر-مصداقية-النطق-بالشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_130/13005.mp3","categories":["الربوبية والألوهية"]},{"id":11101,"question":"سماحة الشيخ له سؤال أخير يقول فيه: إذا كره الإنسان شخصًا آخر، هل يأثم الآخر إذا بادله الكره؟ جزاكم الله خيرًا.","title":"ضابط الكره والبغض للغير ومدته","answer":"الجواب:  هذا يحتاج إلى معرفة الأسباب، إن كان كرهه لأجل إظهاره المعاصي فهذا مأجور، ويستحق الهجر، أما كرهه لأمور أخرى فلا ينبغي هذا، لا ينبغى لأمور دنيوية، ينبغي أن يجاهد نفسه حتى يحبه في الله، والآخر كذلك لا يعامله بالمثل، بل يحبه في الله إذا كان مطيعًا لله مستقيمًا، ولا لمحبته تبعًا لهواه، بل تبعًا للأمور الشرعية، فمن كان مستقيمًا وجب حبه في الله، ولو وجد منه ما تكرهه في حقك؛ لأن الواجب عليك أن تحبه في الله، والآخر يحبك في الله إذا كنت مستقيمًا. وأما أمور الدنيا التي تعرض للناس فلا بأس أن يهجره ثلاثة أيام فأقل، إذا اشتد الأمر واحتاج إلى هذا ثلاثًا، فأقل، الهجر منها فقط، لقول ﷺ: لا هجرة فوق ثلاث نعم، يعني إذا كان في حق المخلوق نزاع بينهم، أو مضاربة، أو ما أشبه ذلك، فلهم أن يتهاجروا أيامًا ثلاثة فقط. أما إذا كان لأجل الله، لمعصية ظاهرة، أو لبدعة هذا يهجر حتى يتوب، ولو شهرًا شهرين أكثر؛ لأن الرسول ﷺ هجر كعب بن مالك وصاحبيه خمسين ليلة؛ بسبب عصيانهم في أمر الجهاد، تخلفوا عن الجهاد بغير عذر. نعم.","link":"https://binbaz.org.sa/fatwas/9279/ضابط-الكره-والبغض-للغير-ومدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29009.mp3","categories":["الربوبية والألوهية"]},{"id":12534,"question":"يسأل هذا السؤال ويقول: ما هي مقتضيات: لا إله إلا الله؟","title":"ما مقتضيات: لا إله إلا الله؟","answer":"الجواب:  هذه الكلمة أعظم كلمة، وهي كلمة التوحيد، ولا يدخل العبد في الإسلام إلا بتحقيقها والإيمان بها، وأنه لا معبود حق إلا الله، وهي أول كلمة دعا إليها الرسل، أول كلمة تدعو إليها الرسل هذه الكلمة: لا إله إلا الله، قال تعالى: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25] وقال سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36] ونبينا محمد ﷺ لما بعثه الله أول كلمة دعا إليها: لا إله إلا الله، مع الإيمان به، وأنه رسول الله، وهي تقتضي إخلاص العبادة لله وحده، والإيمان بأنه المعبود بالحق، وأنه رب العالمين، وأنه الخلاق العليم، وأنه المستحق لأن يعبد ويطاع أمره، وتقتضي أن يؤمن العبد بأن الله هو خالق العبد، وأنه أعد له جنة ونارًا، وأنه لابد من لقائه ربه، فإما الجنة، وإما النار. فهذه الكلمة هي أصل الدين، وأساس الملة، وهي العروة الوثقى؛ فلابد من الإيمان بها، واعتقاد معناها، وأنه لا معبود حق إلا الله، وهذا الاعتقاد يقتضي طاعة الأوامر، وترك النواهي، طاعة ... لله الحق الذي آمنت بأنه معبودك الحق، هي تقتضي أن تؤدي حقه بأن تعبده بصلاتك، وصومك، وزكاتك، وحجك، وصيامك، وغير ذلك، معنى التأله: التعبد، معنى لا إله إلا الله، أي: لا مألوه حق إلا الله، يعني: لا معبود حق إلا الله.  فالواجب عليك أن تألهه، وتعبده بصلاتك، وصومك، وزكاتك، وحجك، وجهادك، وسائر عباداتك، تخص بها الرب  وتعبده وحده، ترجو ثوابه وتخشى عقابه . وهكذا من مقتضياتها أن تؤمن بما حرم الله عليك من الشرك، والمعاصي، وأن تبتعد عن ذلك، وتحذر ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10741/ما-مقتضيات-لا-اله-الا-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40903.mp3","categories":["الربوبية والألوهية"]},{"id":13358,"question":"سماحة الشيخ! هذا السائل يقول: ما هي شروط لا إله إلا الله؛ كلمة التوحيد؟ وهل من قال: لا إله إلا الله فقط دون أن يعمل يدخل الجنة؟","title":"هل من قال: لا إله إلا الله دخل الجنة؟ وما شروطها؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد دلت الأدلة الشرعية من الكتاب والسنة على أن من أتى بالتوحيد، ومات عليه؛ دخل الجنة، من ذلك قوله ﷺ: أمرت أن أقاتل الناس؛ حتى يقولوا: لا إله إلا الله، فإذا قالوها؛ حرمت علي دماؤهم وأموالهم إلا بحقها ومنها حديث عبادة بن الصامت: من شهد أن لا إله إلا الله وحده لا شريك له، وأن محمدًا عبده ورسوله، وأن عيسى عبد الله ورسوله، وكلمته ألقاها إلى مريم، وروح منه، وأن الجنة حق، والنار حق؛ أدخله الله الجنة على ما كان من العمل. ... أحاديث في هذا كثيرة تدل على أن من قال: لا إله إلا الله صادقًا موحدًا، يتضمن كلامه براءته من الشرك، وإيمانه بأن الله هو مستحق العبادة، فإنه يدخل الجنة، ويكون من المسلمين، مع الإيمان بشهادة الأنبياء أن محمدًا رسول الله، والإيمان بكل ما أخبر الله به ورسوله مما بلغه ذاك الوقت. ثم يطالب بعد ذلك بشرائع الإسلام، فإذا أدرك الصلاة وجب أن يصلي، وهكذا الزكاة، هكذا الصيام، هكذا الحج، وإن مات بحال بعد التوحيد دخل الجنة، يعني لو أسلم ومات في الحال؛ دخل الجنة؛ لأنه ما أدرك العمل، ولا فعل شيئًا من السيئة، والإسلام يجب ما قبله، والتوبة تهدم ما كان قبلها، فإن عاش حتى أدرك الصلاة؛ لزمته الصلاة، فإن أبى وجحدها؛ كفر، وإن لم يصل كفر. وهكذا إذا أدرك الزكاة؛ يجب عليه الزكاة، فإن أبى؛ صار عاصيًا يستحق دخول النار، وهكذا إذا أدرك الصيام، ولم يصم؛ صار عاصيًا يستحق دخول النار إلا أن يعفو الله عنه، وهكذا إذا زنى، أو سرق، أو ما أشبه ذلك؛ صار عاصيًا يستحق دخول النار إلا أن يعفو الله عنه، وصار تحت مشيئة الله: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48].  المقصود: أنه متى دخل في الإسلام ووحد الله، وتبرأ من الشرك كله، وآمن بكل ما أخبر الله به ورسوله؛ يكون مسلمًا، ثم يطالب بحقوق الإسلام من صلاة وغيرها، وترك المعاصي، فإن ترك المعاصي، وأدى الحقوق؛ تم إسلامه وإيمانه، وإن مات في الحال قبل أن يدرك شيئًا من الأعمال؛ فله الجنة؛ لأن إسلامه جب ما قبله من الشرور، فإن عاش، فباشر بعض المعاصي، أو ترك بعض الواجبات؛ فهو تحت مشيئة الله، إن شاء الله غفر له، وأدخله الجنة بتوحيده وإن شاء عذبه على قدر المعاصي التي مات عليها، كما تقدم في قوله سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] وهذا بإجماع المسلمين، بإجماع أهل السنة والجماعة.  والعاصي تحت المشيئة لا يكفر؛ خلافًا للخوارج، ولا يخلد في النار كما تقول الخوارج والمعتزلة لا، بل هو تحت مشيئة الله، إذا مات على الزنا، على السرقة، على عقوق الوالدين، على شرب المسكر، على أكل الربا، ولكن لم يستحلها، مقر أنها معاصي، غير مستحل، ولكن غلبه الهوى والشيطان، وإلا هو يعرف أنها معاصي، تحت مشيئة الله، إن شاء الله عفا عنه، وإن شاء عذبه في النار على قدر المعاصي التي مات عليها بعد التطهير والتمحيص، يخرجه الله من النار بإجماع أهل السنة والجماعة، لا يخلد في النار إلا الكفرة؛ خلافًا للخوارج والمعتزلة الذين يقولون: إن العاصي إذا مات على المعصية يخلد في النار، وتقول الخوارج: إنه يكفر، وقولهم باطل عند أهل السنة والجماعة، من أبطل الباطل، والآية الكريمة ترد عليهم وهي قوله سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]. وأما قوله ﷺ في الزاني: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشرب الخمر وهو مؤمن، ولا يسرق السارق حين يسرق وهو مؤمن فالمعنى الوعيد والتحذير، يعني ليس مؤمنًا الإيمان الكامل، عنده نقص في إيمانه، وليس معناه أنه كافر؛ لأن الآيات يصدق بعضها بعضًا، والأحاديث يصدق بعضها بعضًا، وكتاب الله لا يكذب بعضه بعضًا، والسنة لا تخالف القرآن، فوجب أن تفسر النصوص بالنصوص، يفسر النص بالنص.  فقوله: لا يزني الزاني حين يزني وهو مؤمن يعني الإيمان الواجب الكامل، لو كان عنده إيمان كامل ما زنى، لكن عنده نقص، فلهذا وقع في الزنا، وقع في الخمر؛ لنقص إيمانه، ليس معناه أنه كافر؛ لأن الرسول ﷺ أمر في حق الزاني أن يحد، يقام عليه الحد، ويكون الحد كفارة له، وصاحب الخمر كذلك يقام عليه الحد، والحد كفارة له. وإذا مات الزاني على الزنا بعد الحد؛ دخل الجنة، صار الحد كفارة له، ولهذا يقول ﷺ في حديث عبادة في الصحيحين لما ذكر المعاصي قال: فمن أدركه الله في الدنيا يعني بالحدود الشرعية كان كفارة له، ومن أجله الله إلى الآخرة؛ فأمره إلى الله كما قال تعالى: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ[النساء:48].  فأهل السنة والجماعة يقولون: إن صاحب المعاصي تحت المشيئة، إذا كانت معصية دون الشرك، ولم يستحلها؛ فهو تحت المشيئة؛ كالزاني، وشارب الخمر، وآكل الربا، والعاق لوالديه، ونحو ذلك، أما من استحل المعاصي، استحل الزنا، قال: الزنا حلال. تقام عليه الحجة، فإذا بين له الدليل، وأصر على أن الزنا حلال؛ كفر، صار كافرًا الكفر الأكبر، وهكذا من يقول: الخمر حلال، ويبين له الدليل، ويصر يكون كافرًا. وهكذا من يقول: السرقة حلال، أو الربا حلال، يبين له الأدلة، فإذا أصر على أن الربا كله حلال؛ كفر، وهكذا من قال: عقوق الوالدين حلال، يبين له الأمر، فإذا أصر بعد الأدلة؛ كفر، وهكذا من يقول: إن اللواط حلال، وهكذا.. من استحل المعاصي المعروفة من الدين بالضرورة، استحلها، وبين له الدليل وأصر؛ كفر. أما من مات على المعصية وهو يعرف أنها معصية، لم يستحلها، يعرف أنه عاصٍ، مات وهو وزانٍ، مات وهو شارب الخمر، مات وهو يرابي، وهو يعرف أنها معاصي؛ فهذا تحت مشيئة الله، إن شاء ربنا غفر له بأعماله الصالحة، وتوحيده، وإن شاء عذبه على قدر الجريمة التي مات عليها، ثم بعد التطهير والتمحيص في النار يخرجه الله من النار.  وقد تواترت الأحاديث عن الرسول ﷺ: أن كثيرًا من العصاة يدخلون النار، ويعذبون فيها، ثم يخرجهم الله من النار وقد امتحشوا، وقد احترقوا، فيلقون في نهر الحياة، فينبتون كما تنبت الحبة في حمل السيل، فإذا تم خلقهم؛ أدخلهم الله الجنة، وقد تواترت بهذا الأحاديث عن رسول الله ﷺ وأجمع على هذا أهل السنة والجماعة، ولا يبقى في النار مخلد إلا الكفرة -نسأل الله العافية- أما العصاة لا، قد يبقى فيها قد تطول إقامته، ويسمى خلودًا، لكنه خلود مؤقت ينتهي، فإذا تمت المدة التي قدرها الله عليه؛ يخرج من النار، وصار إلى الجنة لتوحيده وإسلامه.  والتوحيد له شروط ذكرها بعض أهل العلم وهي سبعة، قال بعضهم: ثمانية، جمعها بعضهم في بيتين:","link":"https://binbaz.org.sa/fatwas/11643/هل-من-قال-لا-اله-الا-الله-دخل-الجنة-وما-شروطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52401.mp3","categories":["الربوبية والألوهية"]},{"id":13789,"question":"هذا سؤال حقيقة عن العقيدة من السائل من ليبيا (طه . أ. أ) بنغازي يقول: سماحة الشيخ! ما هي أقسام التوحيد؟ وهل المسلم مطلوب منه أن يؤمن بجميع هذه الأقسام؟ وإذا أقر المسلم بالشهادتين فقط هل يكفي ذلك؟","title":"أقسام التوحيد وبيان دخولها ضمن الشهادتين","answer":"الجواب: أقسام التوحيد ثلاثة معروفة بالاستقراء.. وهي: الإيمان بتوحيد الربوبية، والإلهية، والأسماء والصفات، وإذا شهد أن لا إله إلا الله وأن محمدًا رسول الله عن صدق كفى ذلك، ويبين له ما قد يجهل، والرسول ﷺ قبل من الناس من شهد أن لا إله إلا الله وأن محمدًا رسول الله وصدق عمله قوله انقاد للشرع ووحد الله جل وعلا فهو مسلم؛ لأن في ضمن الشهادة الإيمان بأن الله ربه وخالقه، والإيمان بأنه مستحق العبادة، والإيمان بأسمائه وصفاته؛ لأن الشهادة بأنه لا إله إلا الله وأنه المعبود بالحق يتضمن توحيد الربوبية والأسماء والصفات، فإنه سبحانه هو الإله الحق، ومن كان بهذه المثابة فهو رب الجميع وخالق الجميع وهو الكامل في ذاته وأسمائه وصفاته وأفعاله، فتوحيد الربوبية الإيمان بأنه الخلاق الرزاق، وتوحيد الإلهية الإيمان بأنه يستحق العبادة جل وعلا، وأن الآلهة المدعوة معه باطلة سواء كانت جمادًا أو حيوانًا، سواء كان المدعو ملكًا أو نبيًا أو غير ذلك، كل من يدعى من دون الله فعبادته باطلة، ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]، فجميع من يدعى من دون الله معبود بالباطل سواء كان المعبود رسولًا أو ملكًا أو جنيًا أو حجرًا أو شجرًا أو غير ذلك، وهكذا الإيمان بأسماء الله وصفاته، إذا آمن بأن الله سبحانه له الأسماء الحسنى والصفات العلى وأنه الكامل في ذاته وصفاته وأفعاله كفى ذلك، فتوحيد الأسماء والصفات الإيمان بأنه سبحانه موصوف بالأسماء الحسنى والصفات العلى وأنه لا شبيه له ولا نظير له ولا مثل له، والإيمان بالربوبية بأنه هو الخلاق الرزاق مدبر الأمور مصرف الأشياء لا خالق غيره ولا رب سواه، وتوحيد الإلهية معناه الإيمان بأنه مستحق أن يعبد، الإيمان بأنه مستحق لأن يعبد، يدعى، يستغاث به، ينذر له، يذبح له.. إلى غير هذا، هو مستحق للعبادة من صلاة وصوم ودعاء وذبح وغير ذلك لا يستحقها سواه. فإذا أقر بالشهادتين فقد دخل هذا في ضمن شهادته، فإنه إذا شهد أن لا إله إلا الله معناه أنه هو المعبود بالحق، وأنه الخلاق الرزاق، وأنه الكامل في ذاته وأسمائه وصفاته، كل هذا داخل في ضمن الشهادة. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12152/اقسام-التوحيد-وبيان-دخولها-ضمن-الشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53003.mp3","categories":["الربوبية والألوهية"]},{"id":13967,"question":"رسالة وصلت إلى البرنامج من المستمع حسن عثمان حسن سوداني من الإقليم الشمالي، أخونا بعث بأربعة أسئلة، في سؤاله الأول يقول: هل لا إله إلا الله قول باللسان أو قول يحتاج إلى عمل؟","title":"(لا إله إلا الله) قول وعمل","answer":"الجواب: هذه الكلمة هي أعظم كلام الذي يتكلم به الناس، وأفضل الكلام، وهي قول وعمل، ولا يكفي مجرد القول، ولو كفى مجرد القول؛ لكان المنافقون مسلمين، لأنهم يقولونها، وهم مع هذا كفار، بل في الدرك الأسفل من النار، نعوذ بالله من ذلك؛ لأنهم يقولونها باللسان من دون عقيدة ولا إيمان، فلا بد من قولها باللسان مع اعتقاد القلب، وإيمان القلب بأنه لا معبود حق إلا الله، ولا بد أيضًا من أداء حقها بأداء الفرائض وترك المحارم؛ لأن هذا من حق لا إله إلا الله، كما قال عليه الصلاة والسلام: أمرت أن أقاتل الناس حتى يقولوا: لا إله إلا الله، فإذا قالوها؛ عصموا مني دماءهم وأموالهم إلا بحقها وحسابهم على الله، وفي اللفظ الآخر يقول: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله، وأني رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة؛ فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام، وحسابهم على الله ، متفق على صحته.\nفالحاصل: أنه لابد من قول مع يقين، ومع علم، ومع عمل، لا مجرد القول باللسان؛ فـاليهود يقولونها، والمنافقون يقولونها، ولكن لا تنفعهم؛ لما لم يأتوا بالعمل والعقيدة، فلا بد من العقيدة بأنه لا معبود حق إلا الله، وأن ما عبده الناس من أصنام أو أشجار أو أحجار أو قبور أو أنبياء أو ملائكة أو غيرهم: أنه باطل، وأن هذا شرك بالله .\nوالعبادة حق الله وحده ، وهذا هو معنى لا إله إلا الله، فإن معناها: لا معبود حق إلا الله، قال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وقال : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، وقال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:3]، وقال عليه الصلاة والسلام: من قال: لا إله إلا الله، وكفر بما يعبد من دون الله؛ حرم ماله ودمه، وفي اللفظ الآخر عند مسلم: من وحد الله، وكفر بما يعبد من دون الله؛ حرم ماله ودمه. فدل على أنه لا بد من التوحيد والإخلاص لله، ولما بعث النبي ﷺ معاذ إلى اليمن معلمًا ومرشدًا وأميرًا وقاضيًا، قال له: ادعهم إلى أن يوحدوا الله، وفي اللفظ الآخر قال: ادعهم إلى أن يشهدوا أن لا إله إلا الله وأني رسول الله، فإذا فعلوا ذلك؛ فأخبرهم أن الله افترض عليهم خمس صلوات في اليوم والليلة، فإنهم أطاعوك لذلك؛ فأعلمهم أن الله افترض عليهم صدقة تؤخذ من أغنيائهم وترد في فقرائهم.. الحديث.\nوالخلاصة: أنه لابد من الإيمان بها قولًا وعملًا مع النطق، فيشهد أنه لا إله إلا الله عن علم ويقين وإخلاص وصدق ومحبة لما دلت عليه من التوحيد، وانقياد لحقها، وقبول ذلك، وبراءة وكفر بما يعبد من دون الله  هكذا يكون الإيمان بهذه الكلمة. يقولها عن يقين، وأنه لا معبود حق إلا الله، وعن علم ليس فيه جهل ولا شك، وعن إخلاص في ذلك لا رياءً ولا سمعة، وعن محبة لما دلت عليه من التوحيد والإخلاص، وعن صدق لا كالمنافقين يقولها بلسانه وهو يكذب في الباطن، وعن قبول لما دلت عليه من التوحيد وانقياد لذلك، ومحبة لذلك، والتزام به، مع البراءة من كل ما يعبد من دون الله، والكفر بكل ما يعبد من دون الله، كما قال سبحانه: فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى لا انفِصَامَ لَهَا وَاللَّهُ سَمِيعٌ عَلِيمٌ [البقرة:256].  ومعنى الكفر بالطاغوت معناه البراءة من عبادة غير الله، واعتقاد بطلانها، هذا معنى الكفر بالطاغوت، يعني: أن تتبرأ من عبادة غير الله، وأن تعتقد بطلان ذلك، وأن العبادة بحق لله وحده ، ليس له شريك: لا ملك ولا نبي ولا شجر ولا حجر ولا ميت ولا غير ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12384/لا-اله-الا-الله-قول-وعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60508.mp3","categories":["الربوبية والألوهية"]},{"id":16818,"question":"في آخر أسئلة هذا السائل يقول: كلمة التوحيد ما هي شروطها؟","title":"شروط كلمة التوحيد","answer":"الجواب: كلمة التوحيد هي: لا إله إلا الله، فلا بد أن يقولها عن علم، ويقين، لا إله إلا الله، يقول الله -جل وعلا-: فَاعْلَمْ أَنَّهُ لا إِلَهَ إِلَّا اللَّهُ [محمد:19] ويقول سبحانه: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163] ويقول : شَهِدَ اللَّهُ أَنَّهُ لا إِلَهَ إِلَّا هُوَ وَالْمَلائِكَةُ وَأُوْلُوا الْعِلْمِ قَائِمًا بِالْقِسْطِ لا إِلَهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ [آل عمران:18] ويقول : إِلَّا مَنْ شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ [الزخرف:86] ويقول: من قال لا إله إلا الله صدقًا من قلبه وقال: من مات وهو يعلم أن لا إله إلا الله؛ دخل الجنة لا بد من علم، وتصديق، وبصيرة، ومعناها: لا معبود حق إلا الله، هذا معنى لا إله إلا الله. فالذي يقول: لا إله إلا الله، وهو يعبد الأولياء؛ ما قالها، وجودها كعدمها، لا بد أن يقولها، ويعلم معناها، ويعمل، فالذي يقول: لا إله إلا الله، ويدعو الأموات، ويستغيث بالنبي، أو بالبدوي، أو بالحسين، أو بعلي بن أبي طالب، أو بعبد القادر الجيلاني، أو بغيرهم من الأموات، هذا ما قالها، قوله لها باطل، ما ينفع حتى يقولها عن علم، وعن يقين، وعن صدق، وعن محبة، ذكر بعضهم شروطها السبعة، قال:","link":"https://binbaz.org.sa/fatwas/15562/شروط-كلمة-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58515.mp3","categories":["الربوبية والألوهية"]},{"id":16909,"question":"سؤال كبير ليته كان في أول الحلقة يقول صاحبه: ما هو مدلول لا إله إلا الله، وما هي شروطها؟ وما هو معناها؟ وصاحب هذا السؤال هو محمد مفتاح بشير من ليبيا.","title":"معنى لا إله إلا الله وشروطها","answer":"الجواب: لا إله إلا الله هي أفضل الكلام بعد القرآن، هي أحب الكلام إلى الله، وأفضل الكلام، وهي كلمة الإخلاص، وهي أول شيء دعت إليه الرسل -عليهم الصلاة والسلام- وأول شيء دعا إليه النبي ﷺ أن قال لقومه: قولوا: لا إله إلا الله؛ تفلحوا هي كلمة الإخلاص كلمة التوحيد. ومعناها: لا معبود حق إلا الله، هذا معناها كما قال تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62] وهي نفي وإثبات (لا إله) نفي و(إلا الله) إثبات (لا إله) تنفي جميع المعبودات، وجميع الآلهة بغير حق، و(إلا الله) تثبت العبادة بالحق لله وحده  فهي أصل الدين وأساس الملة. والواجب على جميع المكلفين من جن، وإنس أن يأتوا بها رجالًا ونساء، مع إيمان بمعناها، واعتقاد له، وإخلاص العبادة لله وحده. وشروطها ثمانية جمعها بعضهم في بيتين، فقال:","link":"https://binbaz.org.sa/fatwas/15667/معنى-لا-اله-الا-الله-وشروطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71916.mp3","categories":["الربوبية والألوهية"]},{"id":17130,"question":"من الدوادمي رسالة بعث بها مستمع من هناك يقول: محبكم في الله محمد نور الدائم صلاح سوداني مقيم في الدوادمي، الأخ له بعض الأسئلة، يقول في أحدها: لي أخ كان ملتزمًا، إلا أنه الآن ارتكب بعض المعاصي، وحلف أن يتوب، إلا أنني كرهته كرهًا شديدًا، فما هو توجيهكم لي؟ جزاكم الله خيرًا.","title":"الحب والبغض في الله يكون على قدر الطاعة والمعصية","answer":"الجواب: عليك أن تنصحه لله، وأن تحثه على لزوم التوبة، والحمد لله، من تاب تاب الله عليه، تكرهه على المعاصي بقدر معصيته، وتحبه على قدر توحيده لله، وطاعته لله، والقلب يتسع لهذا، قلب المؤمن يتسع للمحبة، والبغضاء، تحبه في الله؛ لأنه مسلم، وتكرهه في الله للمعاصي التي أظهرها، فإذا تاب ورجع إلى الله، رجعت عن بغضه إلى المحبة، فتحبه لله وهو أخوك المؤمن، وإذا أصر على المعصية، ولم يتب صار قلبك يتسع لهذا وهذا، تحبه من جهة إيمانه، ومحبته لله، وتكره ما لديه من المعصية، وتبغضه بقدرها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15955/الحب-والبغض-في-الله-يكون-على-قدر-الطاعة-والمعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72209.mp3","categories":["الربوبية والألوهية"]},{"id":17691,"question":"هذا سائل يا سماحة الشيخ يقول: كيف يحقق المسلم التوحيد؟","title":"كيفية تحقيق المسلم للتوحيد","answer":"الجواب: يحققه باجتناب المعاصي ووسائل الشرك، يحذر وسائل الشرك ويحذر المعاصي، هذا من تحقيق التوحيد، تخليصه وتصفيته من شوائب الشرك والبدع والمعاصي، هذا تحقيقه، الحذر من المعاصي والبدع ووسائل الشرك، هذا هو التحقيق. نعم.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16634/كيفية-تحقيق-المسلم-للتوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59520.mp3","categories":["الربوبية والألوهية"]},{"id":17743,"question":"سماحة الشيخ! تقول هذه السائلة: هل من أساس التوكل على الله عدم الاستعانة بالآخرين لقضاء أمور الدنيا؟","title":"هل من التوكل عدم الاستعانة بالآخرين في أمور الدنيا؟","answer":"الجواب: التوكل على الله يجمع أمرين:\nالاعتماد على الله والثقة به سبحانه، والإيمان بأنه مصرف الأمور ومدبر الأمور، وأنه لا مانع لما أعطى ولا معطي لما منع.\nوالأمر الثاني: الأخذ بالأسباب، فالذي يزعم أنه متوكل ولا يأخذ بالأسباب يسمى عاجزًا مخالفًا للشرع، فالتوكل يجمع الأمرين: الثقة بالله، والاعتماد على الله، والإيمان بأنه مسبب الأسباب، ورازق العباد، وأن ما شاء الله كان، وما لم يشأ لم يكن.\nوالأمر الثاني: الأخذ بالأسباب، غرس الشجر، وحفر البئر للماء، الأكل والشرب، اللباس المناسب في الصيف، واللباس المناسب في الشتاء، توقي الشرور، إغلاق الباب عن السراق، وهكذا.. توقي الشرور، هذا لا بد منه مع التوكل على الله، فالذي يقول: إنه متوكل ومع هذا يهمل الأسباب لا يأكل، ولا يشرب، ولا يبيع، ولا يشتري، ولا يغلق بابه؛ هذا شبه المجنون، هذا خالف الشرع، ويروى عن النبي  أنه قال لبعض الوافدين عليه لما قال: يا رسول الله! هل أعقلها أو أتوكل؟ قال: اعقلها وتوكل اجمع بين الأمرين، اعقل الناقة، وتوكل على الله في أنها تسلم، وأنها لا تقوم ولا يأخذها أحد. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16705/هل-من-التوكل-عدم-الاستعانة-بالاخرين-في-امور-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77706.mp3","categories":["الربوبية والألوهية"]},{"id":17834,"question":"من ليبيا السائل: (عبد الله . أ. أ) يقول: سماحة الشيخ! ما هي أقسام التوحيد، وهل لا بد للإنسان أن يتعرف عليها؟","title":"ما أقسام التوحيد، وهل لا بد للإنسان أن يعرفها؟","answer":"الجواب: أقسام التوحيد ثلاثة: توحيد الإلهية، وتوحيد الربوبية، وتوحيد الأسماء والصفات.\nوإذا عرفها المؤمن ولو ما عرف الأقسام، إذا كان قد وحد الله، وآمن بأن الله ربه، وإلهه، ومعبوده الحق، وأنه ذو الأسماء الحسنى والصفات العلى، لا شبيه له، ولا كفء له؛ كفى ولو لم يعرف الأقسام، لكن إذا عرفها يكون من العلم الطيب.\nفالقسم الأول توحيد الربوبية الذي أقر به المشركون، وهو أن يؤمن العبد بأن الله هو الخلاق الرزاق، هو الذي خلق الجميع، هو الخلاق العليم خلق الأرض، وخلق السماء، وخلق الجن، وخلق بني آدم وخلق كل شيء كما قال سبحانه: اللَّهُ خَالِقُ كُلِّ شَيْءٍ[الرعد:16]، قد أقر بهذا المشركون قال تعالى: وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ[الزخرف:87]، وقال تعالى: قُلْ مَنْ... يعني: قل للمشركين: من يَرْزُقُكُمْ مِنَ السَّمَاءِ وَالأَرْضِ أَمَّنْ يَمْلِكُ السَّمْعَ وَالأَبْصَارَ وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَنْ يُدَبِّرُ الأَمْرَ فَسَيَقُولُونَ اللَّهُ[يونس:31] . يعني: يعترفون بأن ربهم الله هو الخلاق الرزاق المحيي المميت الذي يرزقهم  وهو اللي يدبر الأمور، هذا أقروا به ولكن لم يدخلوه في الإسلام؛ لأنهم لم يأتوا بالتوحيد الثاني وهو توحيد العبادة، وهو تخصيص الله بالعبادة الذي هو معنى: لا إله إلا الله، ومعناها: لا معبود حق إلا الله، وهذا معنى قوله سبحانه في سورة الحج: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ[الحج:62]، ومعنى قوله: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ[البينة:5]، ومعنى قوله: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ[الزمر:2]، ومعنى قوله: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ[الإسراء:23]، ومعنى قوله سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ[الفاتحة:5] لا بد من هذا، وهذا هو الذي جحده المشركون وأنكروه، وجادلوا دونه، وصارت بينهم وبين الرسل العداوة والشحناء، وهدى الله من هدى له ممن سبقت له السعادة، وهو الإيمان بأنه لا معبود حق إلا الله، وهذا هو معنى: لا إله إلا الله، أي: لا معبود حق إلا الله.\nقال جل وعلا: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ[البقرة:163]، وقال سبحانه: فَاعْلَمْ أَنَّهُ لا إِلَهَ إِلَّا اللَّهُ وَاسْتَغْفِرْ لِذَنْبِكَ[محمد:19]، وقال جل وعلا عن المشركين: إِنَّهُمْ كَانُوا إِذَا قِيلَ لَهُمْ لا إِلَهَ إِلَّا اللَّهُ يَسْتَكْبِرُونَ ۝ وَيَقُولُونَ أَئِنَّا لَتَارِكُوا آلِهَتِنَا لِشَاعِرٍ مَجْنُونٍ[الصافات:35-36]، وقال في سورة (ص) عن الكفرة أنهم قالوا: أَجَعَلَ الآلِهَةَ إِلَهًا وَاحِدًا إِنَّ هَذَا لَشَيْءٌ عُجَابٌ[ص:5]، فالمشركون أنكروا هذا؛ لأنهم اعتادوا عبادة الأصنام والشمس، والقمر والنجوم، الكفار أقسام، وكفار العرب اعتادوا عبادة الأصنام والأموات، والأحجار والأشجار كما قال تعالى: أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى ۝ وَمَنَاةَ الثَّالِثَةَ الأُخْرَى ۝ أَلَكُمُ الذَّكَرُ وَلَهُ الأُنثَى ۝ تِلْكَ إِذًا قِسْمَةٌ ضِيزَى ۝ إِنْ هِيَ إِلَّا أَسْمَاءٌ سَمَّيْتُمُوهَا أَنْتُمْ وَآبَاؤُكُمْ مَا أَنزَلَ اللَّهُ بِهَا مِنْ سُلْطَانٍ إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَمَا تَهْوَى الأَنْفُسُ وَلَقَدْ جَاءَهُمْ مِنْ رَبِّهِمُ الْهُدَى[النجم:19-23]، فاللات: رجل صالح كان يلت السويق للحاج، كان يحسن للحجاج يلت لهم السويق، فعبدوه، وعبدوا صخرته التي كان يلت عليها.\nوالعزى: شجرة بين الطائف وبين مكة كانوا يعبدونها، تعبدها قريش وتدعوها، كان فيها جن يلبسون عليهم، ويتكلمون من داخلها.\nومناة: صخرة ..... عند قديد في طريق المدينة كان يعبدها الأنصار وغيرهم، الأوس والخزرج وغيرهم فأنزل الله فيها ما أنزل، وأبطلها.\nوكان حول الكعبة حين دخلها النبي ﷺ وفتح الله عليه ثلاثمائة وستون صنمًا كلها حول الكعبة منها: هبل اللي يعظمونه الذي قال فيه أبو سفيان يوم أحد: «اعل هبل»، قال الرسول ﷺ لهم قولوا: الله أعلى وأجل قال: لنا العزى ولا عزى لكم، قال الرسول ﷺ لهم يوم أحد قولوا: الله مولانا ولا مولى لكم.\nفهذه الآلهة التي يعبدونها من دون الله كلها باطلة سواء كانت من الشجر، أو من الحجر، أو من الأموات، أو من الكواكب أو غيرها، وهذا يسمى توحيد الإلهية وهو معنى: لا إله إلا الله، وهو الذي أنكره المشركون، وجالدوا دونه وقاتلوا، وجاءت به الرسل، ودعت إليه الرسل قال تعالى: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ[النحل:36]، قال تعالى: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ[الأنبياء:25].\nولا بد مع هذا التوحيد من الإيمان بالرسول ﷺ والشهادة بأنه رسول الله، وأنه خاتم الأنبياء .. لا بد من هذا، ولا بد أيضًا من الإيمان بجميع ما أخبر الله به ورسوله مما كان وما يكون، لا يتم التوحيد والإيمان إلا بهذا يعني: لا بد من الإيمان بكل ما أخبر الله به ورسوله في القرآن، أو في السنة الصحيحة من أمر الآخرة والجنة والنار، والحساب والجزاء، والصراط وغير ذلك، ولا بد من الإيمان بأن الله أرسل الرسل، وأنزل الكتب كما بيَّن في كتابه العظيم كالتوراة، والإنجيل، والزبور، وصحف إبراهيم وموسى، كل هذا لا بد منه، يعني: بكل ما أخبر الله به ورسوله. والتوحيد الثالث: توحيد الأسماء والصفات، وهو الإيمان بكل ما أخبر الله به ورسوله عن أسمائه وصفاته لا بد من الإيمان بذلك، وأنه سبحانه له الأسماء الحسنى، وله الصفات العلى، لا شبيه له، ولا كفء له، ولا ند له كما قال : وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا[الأعراف:180]، قال سبحانه بسم الله الرحمن الرحيم: هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ ۝ هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ لَهُ الأَسْمَاءُ الْحُسْنَى يُسَبِّحُ لَهُ مَا فِي السَّمَوَاتِ وَالأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ[الحشر:23-24] لا بد من الإيمان بهذه الأسماء ومعانيها، فله الأسماء الحسنى وله معانيها، هو ذو الرحمة، ذو العلم، ذو القدرة، ذو العزة، ذو الحلم.\nالأسماء لها معاني:\nفالرحمن معناه: الرحمة.\nوالإله معناه: أنه إله الخلق ومعبودهم.\nوالعزيز معناه: العزيز الذي لا يغالب بل قد غلب كل شيء.\nوالرحيم: الذي له الرحمة الواسعة .\nوالحكيم: اللي له الحكمة، لا يفعل شيئًا عبثًا ولا سدى بل كل شيء عن حكمة ليس عبثًا.\nوهكذا هو العليم: الذي يعلم كل شيء ولا يخفى عليه شيء  إلى غير ذلك، هذه أقسام التوحيد الثلاثة.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16827/ما-اقسام-التوحيد-وهل-لا-بد-للانسان-ان-يعرفها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77907.mp3","categories":["الربوبية والألوهية"]},{"id":18040,"question":"نريد من سماحتكم أن توجهوا نداءً للناس تبينوا فيه أهمية الدعوة إلى الله، وتبصير الناس بمعنى لا إله إلا الله؟","title":"الدعوة إلى تبصير الناس حقيقة كلمة التوحيد","answer":"الجواب: في كتاب الله العظيم الكفاية العظيمة، والدعوة إلى هذا الحق العظيم، فقد دعاهم مولاهم سبحانه في كتابه العظيم في آيات كثيرة إلى أن يعبدوه وحده، وهكذا الرسول ﷺ دعاهم إلى ذلك بمكة والمدينة، مدة ثلاث وعشرين سنة، يدعو إلى الله ويبصر الناس بدينهم، كما قال سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ [البقرة:21]، وقال سبحانه: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163]، وقال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، وقال جل وعلا: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3]، وقال سبحانه: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14]، قال : فَاعْلَمْ أَنَّهُ لا إِلَهَ إِلَّا اللَّهُ وَاسْتَغْفِرْ لِذَنْبِكَ [محمد:19].. في آيات كثيرات، وقال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]. وقال النبي ﷺ في الحديث الصحيح: حق الله على العباد أن يعبدوه ولا يشركوا به شيئًا متفق على صحته، وقال عليه الصلاة والسلام: من مات وهو يدعو لله ندًا دخل النار وقال عليه الصلاة والسلام: من لقي الله لا يشرك به شيئًا دخل الجنة، ومن لقيه يشرك به شيئًا دخل النار. فالواجب على جميع أهل الأرض من المكلفين أن يعبدوا الله وحده، وأن يقولوا: لا إله إلا الله، وأن يشهدوا أن محمدًا رسول الله، وأن يخصوا الله بدعائهم وخوفهم ورجائهم واستغاثتهم وصومهم وصلاتهم وسائر عباداتهم، وهكذا طوافهم بالكعبة، يطوفون بالكعبة تقربًا إلى الله وعبادة له وحده ، وأن يحذروا دعوة غير الله من أصحاب القبور أو الأصنام أو الأنبياء أو غير ذلك، فالعبادة حق الله وحده، لا يجوز لأحد أن يصرفها لغيره . والعبادة: اسم جامع لكل ما يحبه الله ويرضاه من الأقوال والأعمال الظاهرة والباطنة، فالصلاة عبادة، والصوم عبادة، والصدقة عبادة، والحج عبادة، وخوف الله عبادة، ورجاؤه عبادة، والنذر عبادة، والذبح عبادة، وهكذا، يجب أن تكون لله وحده، فلا يذبح إلا لله، ولا يصلي إلا لله، ولا يسجد إلا لله، ولا يكون الخوف خوف السر خوف القلوب إلا من الله ، وهكذا لا يستغيث إلا بالله، ولا يطلب المدد إلا منه ؛ لأنه خالقه وربه ومعبوده الحق ، وقد بعث الله الرسل كلهم بذلك، من أولهم إلى آخرهم، من أولهم نوح إلى آخرهم محمد عليه الصلاة والسلام، كلهم يدعون الناس إلى توحيد الله، كما قال : وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36].. وقال سبحانه: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25]، وكان يقول ﷺ لأهل مكة: يا قوم قولوا: لا إله إلا الله تفلحوا. هذا هو الواجب على جميع المكلفين من الرجال والنساء، من العجم والعرب، من الجن والإنس في جميع أرض الله، يجب عليهم أن يعبدوا الله وحده، وأن يقولوا: لا إله إلا الله، وأن يخصوه بالعبادة ، وأن لا يعبدوا معه سواه لا صنمًا ولا نبيًا ولا ملكًا ولا جنيًا ولا شجرًا ولا غير ذلك. العبادة حق الله وحده وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، هذا هو الواجب على جميع المكلفين من جن وإنس، من عرب وعجم، من ذكور وإناث، من ملوك وعامة، يجب على الجميع أن يعبدوا الله وحده، وأن يخصوه بدعائهم وخوفهم ورجائهم وتوكلهم واستغاثتهم ونذورهم وذبحهم وصلاتهم وصومهم ونحو ذلك، كما قال : وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا [النساء:36] .. وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] .. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5]، لكن خوف الإنسان ما يضره، واتخاذ الأسباب، هذا غير داخل في العبادة، فخوفه من اللص حتى يغلق الباب، ويتخذ الحرس، لا حرج في ذلك، كما قال الله عن موسى عليه السلام لما خاف فرعون قال: فَخَرَجَ مِنْهَا خَائِفًا يَتَرَقَّبُ [القصص:21]، يعني: خائف من شر فرعون . فخوف الأمور الحسية، وخوف الظلمة، واتخاذ الأسباب، هذا غير داخل في العبادة، فإذا خاف من اللصوص وأغلق بابه، أو جعل حارسًا على ماله، أو خاف حين سفره من اللصوص أو من قطاع الطريق، وحمل السلاح، وسلك الطريق الآمنة، كل هذا لا بأس به. وهكذا إذا خاف الجوع أكل، خاف الظمأ شرب، خاف البرد لبس ما يدفئه، وما أشبه، هذا كله أمور حسية معروفة، لا حرج فيها، وهكذا إذا استعان بأخيه في مزرعته، في إصلاح سيارته، في بناء بيته، هذه أمور عادية غير داخلة في العبادة، كما قال تعالى: فاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] يعني: موسى، هذه أمور عادية يقدر عليها المخلوق، فالتصرف مع المخلوق الحي الحاضر في أشياء يقدر عليها من تعاون في بناء في مزرعة في جهاد في غير ذلك، هذا غير داخل فيما يتعلق بالعبادة. لكن دعاؤه وهو ميت، دعاء الشجر، دعاء الصنم، دعاء الجن، دعاء الملائكة، دعاء الأنبياء يستغيثه، هذا هو الشرك الأكبر، أو دعاء الحي في أمور لا يقدر عليها، يعتقد فيه أنه له تصرف في الكون، كما يفعل بعض الصوفية مع مشايخهم، يدعونهم مع الله، ويعتقدون فيهم أن لهم تصرفًا في الكون، وأن لهم سرًا يستطيعون معه أن يعلموا الغيب، أو ينفعوا الناس بما لا يقدر عليه إلا الله ، هذه أمور شركية، حتى مع الأحياء نسأل الله السلامة، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا، وتقبل منكم.","link":"https://binbaz.org.sa/fatwas/17072/الدعوة-الى-تبصير-الناس-حقيقة-كلمة-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60005.mp3","categories":["الربوبية والألوهية"]},{"id":18257,"question":"هذا السائل مصري (أ. أ) ومقيم بالمنطقة الشرقية، يقول: سماحة الشيخ! أود أن أتعرف على حقيقة التوكل على الله، ما حقيقة التوكل على الله؟","title":"ما حقيقة التوكل على الله؟","answer":"الجواب: حقيقة التوكل على الله هو الاعتماد عليه  في كل شيء، تعلم أنه مقدر الأمور، ومسبب الأسباب، وأن كل شيء بقضائه وقدره، وتعمل الأسباب تصلي وتصوم، وتعمل الأسباب متوكلًا على الله جل وعلا في حصول المطلوب من دخول الجنة، والنجاة من النار، من ثمرة الزرع، نتاج الحيوان، ربح التجارة، تعمل وتأخذ بالأسباب الشرعية التي شرعها الله، وتعمل معتمدًا على الله جل وعلا، ومتوكلًا عليه في حصول النتيجة المطلوبة من قبول العمل، ومن نجاح الزراعة، من نجاح التجارة، إلى غير ذلك، تعمل وأنت تعلم أن كل شيء بيده، وأنه مسبب الأسباب، ولكنك تأخذ بالأسباب الشرعية والمباحة؛ معتمدًا على الله، راجيًا له أن يسددك، وأن ينفع بأسبابك. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17306/ما-حقيقة-التوكل-على-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78313.mp3","categories":["الربوبية والألوهية"]},{"id":19683,"question":"من أسئلة هذا السائل من الرياض يقول: ما معنى (شهادة أن لا إله إلا الله وأن محمدًا رسول الله)؟","title":"ما معنى الشهادتين؟","answer":"الجواب: معنى الشهادة: أن يشهد بلسانه وبقلبه أنه لا معبود حق إلا الله، يشهد بلسانه ويؤمن بقلبه أنه لا إله إلا الله، يعني: لا معبود حق إلا الله، وأن ما عبده الناس من دون الله من أصنام، أو أموات، أو أشجار، أو أحجار، أو ملائكة أو غيرهم كله باطل كما قال تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]، هذا معنى شهادة أن لا إله إلا الله، أن تشهد عن علم، ويقين، وصدق أنه لا معبود حق إلا الله، وأن ما عبده الناس من دون الله فكله باطل. ومعنى شهادة (أن محمدًا رسول الله) أن تشهد عن علم ويقين، وصدق أن محمد بن عبد الله بن عبد المطلب هو رسول الله حقًا إلى جميع الثقلين جنهم وإنسهم، وأنه خاتم الأنبياء ليس بعده نبي عليه الصلاة والسلام. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18975/ما-معنى-الشهادتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95036.mp3","categories":["الربوبية والألوهية"]}]
